"use strict";
(()=>{
 const lessons=window.LEARNWITHUS_LANGUAGE_LESSONS||{},params=new URLSearchParams(location.search),lang=params.get('lang')==='te'?'te':'hi',lesson=lessons[lang],root=document.getElementById('languageQuizRoot');if(!lesson||!root)return;
 const letters=lesson.rows.flat().map(([letter,roman])=>({letter,roman})),shuffle=a=>[...a].sort(()=>Math.random()-.5),items=shuffle(letters).slice(0,10);let index=0,score=0;
 const title=document.getElementById('languageQuizTitle');if(title)title.textContent=lesson.name+' Letters Quiz';
 const speakEnglish=text=>{if(!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-IN';u.rate=.78;window.speechSynthesis.speak(u)};
 function finish(){root.innerHTML='<section class="practice-box"><p class="game-progress">Quiz complete</p><p class="game-question">'+score+' / 10</p><p class="game-feedback">'+(score===10?'Excellent work!':'Good work! Review the letters and try again.')+'</p><div id="sharedScoreCard"></div><div class="journey-actions"><button id="languageAgain" class="practice-button journey-primary">Play again</button><a class="practice-button journey-secondary" href="'+(lang==='hi'?'hindi.html':'telugu.html')+'">← Review '+lesson.name+' Letters</a><a class="practice-button journey-secondary" href="'+(lang==='hi'?'telugu.html':'children.html?mode=words')+'">Next: '+(lang==='hi'?'Telugu':'Phonics')+' →</a></div></section>';window.renderLearnWithUsScoreCard?.({container:document.getElementById('sharedScoreCard'),score,total:10,title:lesson.name+' Letters Quiz',subtitle:'Recognise the script and its reading guide.',filename:'learnwithus-'+lang+'-letters-score.svg',url:'language-quiz.html?lang='+lang});window.LearnWithUs?.recordQuiz?.(lesson.name+' letters quiz',score,10,'language-quiz.html?lang='+lang);document.getElementById('languageAgain').onclick=()=>location.reload();}
 function round(){if(index>=10)return finish();const item=items[index],wrong=shuffle(letters.filter(x=>x.roman!==item.roman).map(x=>x.roman).filter((x,i,a)=>a.indexOf(x)===i)).slice(0,3);root.innerHTML='<section class="practice-box"><p class="game-progress">Question '+(index+1)+' of 10</p><p class="game-question language-quiz-glyph" lang="'+lang+'">'+item.letter+'</p><p class="game-feedback">Which reading guide matches this letter?</p><div class="game-options" id="languageQuizOptions"></div><p class="game-feedback" id="languageQuizFeedback" role="status" aria-live="polite"></p><button class="practice-button game-next" id="languageQuizNext" hidden>'+(index===9?'See score →':'Next →')+'</button></section>';const row=document.getElementById('languageQuizOptions'),fb=document.getElementById('languageQuizFeedback'),next=document.getElementById('languageQuizNext');shuffle([item.roman,...wrong]).forEach(v=>{const b=document.createElement('button');b.type='button';b.textContent=v;b.onclick=()=>{const ok=v===item.roman;row.querySelectorAll('button').forEach(x=>{x.disabled=true;if(x.textContent===item.roman)x.classList.add('correct')});b.classList.add(ok?'correct':'wrong');const msg=ok?'Correct answer! It is '+item.roman+'.':'Wrong answer. The correct answer is '+item.roman+'.';fb.textContent=msg;speakEnglish(msg);if(ok)score++;next.hidden=false;next.focus();};row.append(b)});next.onclick=()=>{index++;round()};}
 round();
})();